(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[195],{7286:function(e,t,i){(window.__NEXT_P=window.__NEXT_P||[]).push(["/blog",function(){return i(4739)}])},4739:function(e,t,i){"use strict";i.r(t),i.d(t,{default:function(){return a}});var s=i(5893);function a(){return(0,s.jsxs)("section",{className:"space-y-8",children:[(0,s.jsxs)("header",{className:"space-y-1",children:[(0,s.jsx)("h1",{className:"text-2xl md:text-3xl font-extrabold tracking-tight text-berkeleyBlue mt-2",children:"Blog Series"}),(0,s.jsx)("p",{className:"text-base md:text-lg text-primary/80",children:"Insights and case studies from AI-Driven Research Systems (ADRS)."})]}),(0,s.jsx)("div",{className:"space-y-5",children:[{title:"Automating Algorithm Discovery: A Case Study in Policy Optimization with Bauplan",author:"Bauplan & ADRS Teams",date:"January 15, 2026",excerpt:"This post is the tenth in our ADRS series, where we use AI to automatically discover better algorithms for real-world systems problems. In this blog, we partner with Bauplan to explore how ADRS can optimize policy generation for data pipeline systems. By combining simulation-driven evaluation with an evolutionary search loop, we demonstrate how AI can iteratively refine scheduling policies and configuration parameters, achieving significant performance improvements over hand-tuned baselines.",image:"/bauplan.jpg",url:"https://adrs-ucb.notion.site/bauplan"},{title:"Automating Algorithm Discovery: A Case Study in Optimizing LLM Serving with Prism",author:"ADRS Team",date:"January 8, 2026",excerpt:"This post is the ninth in our ADRS series, where we use AI to automatically discover better algorithms for real-world systems problems. In this blog, we explore the challenges of managing GPU memory for LLM inference serving. We highlight Prism, a system that optimizes memory management and model placement. By leveraging an exact-caching mechanism and optimized scheduling, Prism achieves ~70% cost savings compared to static assignments, allowing for significantly higher throughput and efficiency in serving workloads.",image:"/prism.jpg",url:"https://adrs-ucb.notion.site/prism"},{title:"Let the Barbarians In: How AI Can Accelerate Systems Performance Research",author:"ADRS Team",date:"January 2, 2026",excerpt:"This post is the eighth in our ADRS series, which expands upon our work on AI-Driven Research for Systems (ADRS). We evaluate three open-source frameworks across ten real-world research problems, demonstrating their ability to generate solutions that outperform human experts, including a 13x speedup in load balancing and 35% cost savings in cloud scheduling. Based on these findings, we outline best practices for problem specification, evaluation, and feedback, providing a roadmap for applying these tools effectively.",image:"/adrs-2.png",url:"https://adrs-ucb.notion.site/let-the-barbarians-in"},{title:"Automating Algorithm Discovery: A Case Study in Improving Multi-Agent System Design using MAST",author:"ADRS Team",date:"December 15, 2025",excerpt:"This post is the seventh in our ADRS series, where we use AI to automatically discover better algorithms for real-world systems problems. Designing effective multi-agent systems typically requires debugging workloads via execution logs and iteratively refining the agentic systems\u2019 behavior. Previously, we demonstrated how the MAST Annotator provides scalable, systematic feedback on failure modes to guide agents builders to make design improvements. However, that approach still relied on hand-crafted solutions and implementations. In this blog, we replace hand-tuning with OpenEvolve to optimize the Multi-Agent System (MAS) code directly. By leveraging MAST feedback, OpenEvolve continuously mutates the architecture, automatically converging toward a more reliable system, improving failure rates by 7x.",image:"/mast.png",url:"https://adrs-ucb.notion.site/mast"},{title:"BitsEvolve: Self-Optimizing GPU Code Generation at Datadog",author:"Datadog & ADRS Team",date:"December 4, 2025",excerpt:"This post is the sixth in our ADRS series, where we explore how AI can be applied to systems research. We feature exciting work from Datadog this week! In this blog post, we examine the problem of generating production-ready, optimized GPU code from an evolutionary search perspective. Specifically, we share results from BitsEvolve, an ADRS framework built at Datadog that targets various modalities ranging from optimizing hotspots in CPU-bound code to policy/configuration tuning for applications like inference serving frameworks (e.g. vLLM), Load Balancers, Garbage Collectors and more. Through profile guidance and robust evaluation mechanisms, we show how BitsEvolve-generated code can outperform compiled models, achieving speedups of up to 1.6x with reasonable search costs.",image:"/datadog.png",url:"https://adrs-ucb.notion.site/datadog"},{title:"Autocomp: An ADRS Framework for Optimizing Tensor Accelerator Code",author:"Autocomp & ADRS Teams",date:"November 20, 2025",excerpt:"This post is the fifth in our ADRS series, where we explore how AI can be applied to systems research. This post was contributed by a team of our colleagues at UC Berkeley\u2019s SLICE Lab! In this blog post, we go down the stack and explore how AI is being used to speed up AI\u2014at the kernel level. Specifically, we highlight Autocomp, the first LLM-driven code optimizer for low-resource tensor accelerators. Autocomp helps hardware designers extract the full performance of tensor accelerators, outperforming human expert kernel writers by up to 17x on AWS Trainium while being highly portable and easy to use.",image:"/autocomp.png",url:"https://adrs-ucb.notion.site/autocomp"},{title:"Automating Algorithm Discovery: A Case Study in Transaction Scheduling",author:"ADRS Team",date:"November 13, 2025",excerpt:"This post is the fourth in our ADRS series. In this blog, we revisit a recent research problem from our VLDB \u201824 paper, Towards Optimal Transaction Scheduling, which minimizes contention for database transactional workloads. We show how we leverage an ADRS framework to discover an algorithm with 34% faster schedules. This case study shows how AI can be used to develop solutions for different problem settings that would otherwise require manual redesign.",image:"/transaction.png",url:"https://adrs-ucb.notion.site/txn-scheduling"},{title:"Automating Algorithm Discovery: A Case Study in Optimizing LLM Queries over Relational Workloads",author:"ADRS Team",date:"November 6, 2025",excerpt:"This post is the third in our ADRS series, where we use AI to automatically discover better algorithms for real-world systems problems. In this blog, we revisit a recent research challenge from our MLSys\u201925 paper, \u201cOptimizing LLM Queries in Relational Data Analytics Workloads \u201d, which tackles the high cost and latency of executing LLM queries over relational data. We show how using OpenEvolve, ADRS autonomously discovered a 3\xd7 faster algorithm that achieves the same prefix reuse ratio as the published solution.",image:"/llmqueries.png",url:"https://adrs-ucb.notion.site/llm-sql-evolution"},{title:"Automating Algorithm Discovery: A Case Study in Spot Instance Scheduling",author:"ADRS Team",date:"October 30, 2025",excerpt:"This post is the second in our ADRS series, where we apply AI to optimize complex system problems. Here, we tackle spot instance scheduling, a classic cost-versus-reliability problem in the cloud. Specifically, we demonstrate how OpenEvolve discovers novel algorithms that surpass the algorithm from an NSDI'24 Best Paper, achieving up to 16% and 48% cost savings in a single and multi-region setups, respectively.",image:"/spot.png",url:"https://adrs-ucb.notion.site/spot-instance-scheduling"},{title:"Automating Algorithm Discovery: A Case Study in MoE Load Balancing",author:"ADRS Team",date:"October 23, 2025",excerpt:"This post is the first in a series of case studies in which we apply ADRS to optimize performance in various systems. In this blog, we discuss the optimization of a key component in large language model (LLM) inference. Specifically, we demonstrate how OpenEvolve independently discovers and surpasses highly optimized algorithms engineered by human experts to achieve a 5.0x speedup.",image:"/moe.png",url:"https://adrs-ucb.notion.site/moe-load-balancing"},{title:"Barbarians at The Gate: How AI is Upending Systems Research",author:"ADRS Team",date:"October 17, 2025",excerpt:'AI is no longer just tuning systems as a "black box." It\'s now rewriting their core algorithms by treating the system as a "white box" and discovering solutions that can outperform human experts. This new approach, which we term AI-Driven Research for Systems (ADRS), can automate some of the most tedious parts of reseach.',image:"/image1.png",url:"https://adrs-ucb.notion.site/"}].map((function(e,t){return(0,s.jsx)("a",{href:e.url,target:"_blank",rel:"noopener noreferrer",className:"block rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-shadow no-underline","aria-label":"Read ".concat(e.title," on Notion"),children:(0,s.jsxs)("div",{className:"bg-white md:flex md:items-stretch",children:[(0,s.jsx)("div",{className:"md:basis-4/12 bg-white flex items-center justify-center p-3",children:(0,s.jsx)("img",{src:e.image,alt:e.title,className:"w-full h-32 md:h-36 object-contain"})}),(0,s.jsxs)("div",{className:"md:basis-8/12 bg-berkeleyBlue text-white p-4 md:p-5",children:[(0,s.jsx)("h2",{className:"text-lg md:text-xl font-semibold tracking-normal",style:{lineHeight:"1.1"},children:e.title}),(0,s.jsxs)("p",{className:"mt-1 text-white/70 text-[10px] md:text-xs border-b border-white/20 pb-1.5",children:["by: ",e.author,", ",e.date]}),(0,s.jsx)("p",{className:"mt-2 text-white/90 text-sm leading-tight line-clamp-3",children:e.excerpt})]})]})},t)}))})]})}}},function(e){e.O(0,[774,888,179],(function(){return t=7286,e(e.s=t);var t}));var t=e.O();_N_E=t}]);